            save_output(image_path.name, result)

        except Exception as e:
            error_msg = f"Error processing {image_path.name}: {str(e)}"
            print(f"      ❌ {error_msg}")
            errors.append(error_msg)

            # Save error record
            error_result = {
                "source_file": image_path.name,
                "source_path": str(image_path),
                "processed_at": datetime.now().isoformat(),
                "error": str(e),
                "metadata": {"file_name": image_path.name},
                "detected_objects": [],
                "faces": [],
                "captions": ["Error during processing"],
                "embeddings": {},
                "tags": {"combined": [], "object_detection": [], "filename_derived": [], "caption_derived": []}
